# Downloads every GCSE past paper, mark scheme and Maths Genie sheet used by Kenz's revision site.
# Files go into a "gcse-papers" folder next to this script. Re-run any time: finished files are skipped.
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$dir = Join-Path $PSScriptRoot 'gcse-papers'
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$ua = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36'
