https://old-asset.mathsgenie.co.uk/resources/2-stem-and-leaf-diagrams.pdf	mathsgenie.co.uk__resources_2-stem-and-leaf-diagrams.pdf
https://old-asset.mathsgenie.co.uk/resources/2-stem-and-leaf-diagramsans.pdf	mathsgenie.co.uk__resources_2-stem-and-leaf-diagramsans.pdf
https://old-asset.mathsgenie.co.uk/resources/3-exchange-rates.pdf	mathsgenie.co.uk__resources_3-exchange-rates.pdf
https://old-asset.mathsgenie.co.uk/resources/3-exchange-ratesans.pdf	mathsgenie.co.uk__resources_3-exchange-ratesans.pdf
https://old-asset.mathsgenie.co.uk/resources/3-linear-graphs.pdf	mathsgenie.co.uk__resources_3-linear-graphs.pdf
https://old-asset.mathsgenie.co.uk/resources/3-linear-graphsans.pdf	mathsgenie.co.uk__resources_3-linear-graphsans.pdf
https://old-asset.mathsgenie.co.uk/resources/3-two-way-tables.pdf	mathsgenie.co.uk__resources_3-two-way-tables.pdf
https://old-asset.mathsgenie.co.uk/resources/3-two-way-tablesans.pdf	mathsgenie.co.uk__resources_3-two-way-tablesans.pdf
'@ -split "`r?`n" | Where-Object { $_.Trim() }
$total = $list.Count; $i = 0; $ok = 0; $skip = 0; $fail = @()
foreach ($line in $list) {
  $i++
  $u, $n = $line.Trim() -split "`t"
  $out = Join-Path $dir $n
  if ((Test-Path -LiteralPath $out) -and ((Get-Item -LiteralPath $out).Length -gt 2000)) { $skip++; continue }
  Write-Host ("[{0}/{1}] {2}" -f $i, $total, $n)
  $done = $false
  foreach ($try in 1..3) {
    try {
      Invoke-WebRequest -Uri $u -OutFile $out -UserAgent $ua -UseBasicParsing -TimeoutSec 90 -Headers @{ Referer = 'https://www.physicsandmathstutor.com/' }
      $b = [byte[]](Get-Content -LiteralPath $out -Encoding Byte -TotalCount 4)
      if ($b.Count -eq 4 -and $b[0] -eq 0x25 -and $b[1] -eq 0x50 -and $b[2] -eq 0x44 -and $b[3] -eq 0x46) { $done = $true; break }
      Remove-Item -LiteralPath $out -ErrorAction SilentlyContinue
    } catch { Remove-Item -LiteralPath $out -ErrorAction SilentlyContinue }
    Start-Sleep -Seconds (2 * $try)
  }
  if ($done) { $ok++ } else { $fail += $u; Write-Host "   could not get this one" -ForegroundColor Yellow }
  Start-Sleep -Milliseconds 300
}
$fail | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'gcse-papers-failed.txt')
Write-Host ""
Write-Host ("Done: {0} downloaded, {1} already there, {2} failed (listed in gcse-papers-failed.txt)." -f $ok, $skip, $fail.Count) -ForegroundColor Green
Write-Host "Now open the revision site > Exams & papers > Import papers folder, and pick the gcse-papers folder."
